-- Workspace keybindings
for i = 0, 9 do
	local workspace = i == 0 and 10 or i

	hl.bind(mainMod .. " + " .. i, hl.dsp.focus({ workspace = workspace }))
	hl.bind(mainMod .. " + SHIFT + " .. i, hl.dsp.window.move({ workspace = workspace, follow = false }))
end

hl.bind(mainMod .. " + S", hl.dsp.workspace.swap_monitors({ monitor1 = "HDMI-A-1", monitor2 = "eDP-1" }))

hl.bind(mainMod .. " + SHIFT + bracketleft", hl.dsp.window.move({ workspace = -1, follow = false }))
hl.bind(mainMod .. " + SHIFT + bracketright", hl.dsp.window.move({ workspace = "+1", follow = false }))

hl.bind("mouse:275", hl.dsp.exec_cmd(volume .. " --dec"))
hl.bind("mouse:276", hl.dsp.exec_cmd(volume .. " --inc"))

